int receive_message_from_socket(struct kiocb *iocb, struct socket *sock, struct msghdr *msg, size_t size, int flags) {
    struct sock *sk = sock->sk;
    struct sk_buff *skb;
    int copied = 0;
    int err = 0;

    if (!sk) {
        return -EINVAL;
    }

    if (size == 0) {
        return 0;
    }

    skb = skb_recv_datagram(sk, flags, &err);
    if (!skb) {
        return err;
    }

    copied = skb->len;
    if (copied > (int)size) {
        if (!(flags & MSG_TRUNC)) {
            skb_trim(skb, size);
            copied = size;
        }
    }

    if (copied > 0) {
        err = skb_copy_datagram_msg(skb, 0, msg, copied);
        if (err) {
            kfree_skb(skb);
            return err;
        }

        if (!(flags & MSG_PEEK)) {
            sock_recv_timestamp(msg, sk, skb);
            __sock_put(sk);
        }
    }

    kfree_skb(skb);
    return copied;
}
